WITH base AS (SELECT *, IF(is_flagged, 'Yes', 'No') AS is_flagged_label, COALESCE(merchant, 'OTHER') AS merchant_filled FROM transactions WHERE txn_time >= DATE '2023-11-28' AND txn_type = 'DEBIT') SELECT *, ROW_NUMBER() OVER (PARTITION BY account_id ORDER BY amount, id) AS event_seq, LAST_VALUE(merchant) IGNORE NULLS OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_merchant FROM base
